1	package tariff
2	
3	import (
4		"fmt"
5		"testing"
6		"time"
7	)
8	
9	// 交接场景的固定时间线（费率时间以东八区表示）：
10	//
11	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 (+08:00) 起生效，登记结束 2026-03-31 00:00 (+08:00)
12	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 (+08:00) 起替代旧版，无结束时间
13	//
14	// 东八区 2026-03-10 00:00 即 UTC 2026-03-09 16:00，是同一实际时刻。
15	var (
16		east8           = time.FixedZone("UTC+8", 8*3600)
17		handoffOldEnd   = time.Date(2026, 3, 31, 0, 0, 0, 0, east8)
18		handoffPoint    = time.Date(2026, 3, 10, 0, 0, 0, 0, east8)
19		handoffPointUTC = time.Date(2026, 3, 9, 16, 0, 0, 0, time.UTC)
20	)
21	
22	// newHandoffBook 返回一本已登记 seat-v1/seat-v2 交接关系的账本及其时钟。
23	func newHandoffBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
24		t.Helper()
25		if !handoffPoint.Equal(handoffPointUTC) {
26			t.Fatal("测试前提不成立：东八区 3 月 10 日零点应等于 UTC 3 月 9 日 16 点")
27		}
28		now, setNow := fixedClock(start)
29		b := NewBook(WithClock(now))
30		if err := b.RegisterVersion(RegisterRequest{
31			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
32			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, east8),
33			End:   &handoffOldEnd,
34		}); err != nil {
35			t.Fatalf("register seat-v1: %v", err)
36		}
37		if err := b.RegisterVersion(RegisterRequest{
38			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
39			Start:    handoffPoint,
40			Replaces: "seat-v1",
41		}); err != nil {
42			t.Fatalf("register seat-v2: %v", err)
43		}
44		return b, setNow
45	}
46	
47	// 版本视图：旧版登记结束仍显示月底，实际有效结束显示交接点；新版保留替代来源。
48	func TestHandoffVersionView(t *testing.T) {
49		b, _ := newHandoffBook(t, time.Date(2026, 3, 1, 0, 0, 0, 0, east8))
50	
51		views, err := b.ItemVersions("seat")
52		if err != nil {
53			t.Fatal(err)
54		}
55		if len(views) != 2 {
56			t.Fatalf("want 2 versions, got %d", len(views))
57		}
58		old, nv := views[0], views[1]
59		if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
60			t.Fatalf("unexpected order: %v, %v", old.VersionID, nv.VersionID)
61		}
62	
63		// 旧版：登记结束仍是 3 月 31 日零点，实际有效结束被截断到交接点。
64		if old.End == nil || !old.End.Equal(handoffOldEnd) {
65			t.Fatalf("registered end must stay at month end: %v", old.End)
66		}
67		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(handoffPoint) {
68			t.Fatalf("effective end must be the handoff point: %v", old.EffectiveEnd)
69		}
70		if old.SupersededBy != "seat-v2" {
71			t.Fatalf("old superseded-by: %q", old.SupersededBy)
72		}
73	
74		// 新版：保留替代旧版的来源，未设结束时间。
75		if nv.Replaces != "seat-v1" {
76			t.Fatalf("new version must keep replacement source: %q", nv.Replaces)
77		}
78		if nv.End != nil || nv.EffectiveEnd != nil {
79			t.Fatalf("new version should be open-ended: %+v", nv)
80		}
81		if nv.UnitPrice != 180 {
82			t.Fatalf("new unit price: %d", nv.UnitPrice)
83		}
84	}
85	
86	// 交接点前后一纳秒及交接点本身的报价边界。
87	func TestHandoffBoundaryQuotes(t *testing.T) {
88		b, setNow := newHandoffBook(t, handoffPoint.Add(-time.Nanosecond))
89	
90		cases := []struct {
91			name      string
92			instant   time.Time
93			versionID string
94			confirmed bool
95			unitPrice int64
96			total     int64
97			reason    RejectReason
98		}{
99			{"交接点前1纳秒-旧版确认", handoffPoint.Add(-time.Nanosecond), "seat-v1", true, 150, 600, ReasonNone},
100			{"交接点前1纳秒-新版尚未生效", handoffPoint.Add(-time.Nanosecond), "seat-v2", false, 0, 0, ReasonVersionNotYetEffective},
101			{"交接点本身-旧版已失效", handoffPoint, "seat-v1", false, 0, 0, ReasonVersionExpired},
102			{"交接点本身-新版确认", handoffPoint, "seat-v2", true, 180, 720, ReasonNone},
103			{"交接点后1纳秒-旧版已失效", handoffPoint.Add(time.Nanosecond), "seat-v1", false, 0, 0, ReasonVersionExpired},
104			{"交接点后1纳秒-新版确认", handoffPoint.Add(time.Nanosecond), "seat-v2", true, 180, 720, ReasonNone},
105		}
106		for i, c := range cases {
107			setNow(c.instant)
108			req := QuoteRequest{
109				RequestID: fmt.Sprintf("handoff-%02d", i),
110				ItemID:    "seat",
111				VersionID: c.versionID,
112				Quantity:  4,
113			}
114			out, err := b.Quote(req)
115			if err != nil {
116				t.Fatalf("%s: 拒绝/确认都是正常受理，err 应为空，got %v", c.name, err)
