136	
137	// 同一个实际时刻换成另一种时区表示，确认状态、金额和拒绝原因都应一致。
138	func TestHandoffSameInstantAnyTimezone(t *testing.T) {
139		b, setNow := newHandoffBook(t, handoffPointUTC)
140	
141		type want struct {
142			confirmed bool
143			unitPrice int64
144			total     int64
145			reason    RejectReason
146		}
147		instants := []struct {
148			name    string
149			instant time.Time
150			oldV    want
151			newV    want
152		}{
153			{
154				"交接点前1纳秒",
155				handoffPoint.Add(-time.Nanosecond),
156				want{true, 150, 600, ReasonNone},
