232	// 新版已有效时，指定旧版的报价必须保留旧版来源并拒绝，不能自动换版计算。
233	func TestHandoffNoAutoVersionSwitch(t *testing.T) {
234		b, _ := newHandoffBook(t, handoffPoint.Add(time.Hour))
