257	// 交接前确认的 600 分报价，交接后按原标识查询仍保留首次结果，不按当前费率重算。
258	func TestHandoffConfirmedQuoteSurvives(t *testing.T) {
259		acceptedAt := time.Date(2026, 3, 2, 10, 0, 0, 0, east8)
260		b, setNow := newHandoffBook(t, acceptedAt)
261	
262		req := QuoteRequest{RequestID: "keep-600", ItemID: "seat", VersionID: "seat-v1", Quantity: 4}
263		first, err := b.Quote(req)
264		if err != nil || !first.Confirmed {
265			t.Fatalf("交接前报价应确认: %v %+v", err, first)
266		}
267		if first.UnitPrice != 150 || first.Total != 600 {
268			t.Fatalf("交接前金额: 单价=%d 总价=%d", first.UnitPrice, first.Total)
269		}
270		if !first.AcceptedAt.Equal(acceptedAt) {
271			t.Fatalf("首次受理时刻: %v", first.AcceptedAt)
272		}
273	
274		// 推进到交接点之后：旧版已失效，新版 180 分已生效。
275		setNow(handoffPoint.Add(24 * time.Hour))
276	
277		got, err := b.Lookup("keep-600")
278		if err != nil {
279			t.Fatal(err)
280		}
281		if got != first {
282			t.Fatalf("历史报价被重算: %+v -> %+v", first, got)
283		}
284		if got.Request.VersionID != "seat-v1" || got.Request.Quantity != 4 ||
285			got.UnitPrice != 150 || got.Total != 600 || !got.AcceptedAt.Equal(acceptedAt) {
286			t.Fatalf("历史报价未保留原版本/数量/金额/受理时刻: %+v", got)
287		}
288	
289		// 原样重试同样返回首次结果，而不是按当前费率重算。
290		replay, err := b.Quote(req)
291		if err != nil {
292			t.Fatal(err)
293		}
294		if replay != first {
295			t.Fatalf("重试结果被重算: %+v -> %+v", first, replay)
296		}
297	}
