219					t.Fatalf("第%d轮: 新版本开始时刻应为 3 月 10 日: %+v", round+1, nv)
220				}
221				if nv.End == nil || !nv.End.Equal(rrFollowStart) ||
222					nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(rrFollowStart) {
223					t.Fatalf("第%d轮: 新版本有效区间应为 [03-10, 04-01): 登记结束=%v 实际结束=%v",
224						round+1, nv.End, nv.EffectiveEnd)
225				}
226				if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
227					t.Fatalf("第%d轮: 新版本替代关系异常: Replaces=%q SupersededBy=%q",
228						round+1, nv.Replaces, nv.SupersededBy)
229				}
230	
231				// 后续版本：边界与替代关系保持登记时的原值。
232				if follow.UnitPrice != 200 || !follow.Start.Equal(rrFollowStart) {
233					t.Fatalf("第%d轮: 后续版本登记信息异常: %+v", round+1, follow)
234				}
235				if follow.End != nil || follow.EffectiveEnd != nil {
236					t.Fatalf("第%d轮: 后续版本应仍持续有效: 登记结束=%v 实际结束=%v",
237						round+1, follow.End, follow.EffectiveEnd)
238				}
239				if follow.Replaces != "" || follow.SupersededBy != "" {
240					t.Fatalf("第%d轮: 后续版本不应出现替代关系: Replaces=%q SupersededBy=%q",
241						round+1, follow.Replaces, follow.SupersededBy)
242				}
243			})
244		}
245	}
246	
247	// timePtr 返回时间的指针，供表驱动用例填写结束时刻。
248	func timePtr(t time.Time) *time.Time {
249		return &t
250	}
