308			for i := 1; i < len(reprs); i++ {
309				if !reprs[0].Equal(reprs[i]) {
310					t.Fatalf("测试前提不成立：%v 与 %v 不代表同一瞬间", reprs[0], reprs[i])
311				}
312			}
313	
314			first, errFirst := b.EffectiveVersionAt("seat", reprs[0])
315			for r := 1; r < len(reprs); r++ {
316				got, err := b.EffectiveVersionAt("seat", reprs[r])
317				if !errors.Is(err, errFirst) {
318					t.Fatalf("瞬间 %v 用表示 %v 查询: err=%v，与 UTC 表示的 %v 不一致",
319						instant, reprs[r], err, errFirst)
320				}
321				if errFirst == nil && got.VersionID != first.VersionID {
322					t.Fatalf("瞬间 %v 用表示 %v 选中 %q，UTC 表示选中 %q",
323						instant, reprs[r], got.VersionID, first.VersionID)
324				}
325			}
326		}
327	
328		// 题目指定的对照：03:00Z 与东八区 11:00 是同一瞬间，两处都应得到
329		// ErrNoEffectiveVersion，不能因表示不同而一个报错、一个恢复旧版。
330		_, errUTC := b.EffectiveVersionAt("seat", xtzNewEndUTC)
331		_, errEast := b.EffectiveVersionAt("seat", time.Date(2026, 3, 1, 11, 0, 0, 0, east8))
332		if !errors.Is(errUTC, ErrNoEffectiveVersion) || !errors.Is(errEast, ErrNoEffectiveVersion) {
333			t.Fatalf("03:00Z 与 11:00+08 是同一瞬间，都应无生效版本: %v %v", errUTC, errEast)
334		}
335	}
336	
337	// TestCrossTimezoneInvalidIntervalEndEqualsStart 失败边界一：
338	// 新版仍从 02:00Z 开始，结束填 10:00 (+08:00)，两者实际相等，
339	// 必须返回 ErrInvalidInterval（而不是先报替代关系错误），且整次登记回滚；
340	// 把结束修正为 11:00 (+08:00)（03:00Z）后，同一新版标识仍能登记成功。
341	func TestCrossTimezoneInvalidIntervalEndEqualsStart(t *testing.T) {
342		b := newXtzOldOnlyBook(t)
343	
344		// 先钉死失败前提：10:00+08 与 02:00Z 实际相等。
345		if !xtzBadEndEqualStart.Equal(xtzNewStart) {
346			t.Fatal("测试前提不成立：失败边界一的结束应恰好等于新版开始")
347		}
348	
349		badEnd := xtzBadEndEqualStart
350		err := b.RegisterVersion(RegisterRequest{
351			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
352			Start: xtzNewStart, End: &badEnd, Replaces: "seat-v1",
353		})
354		if !errors.Is(err, ErrInvalidInterval) {
355			t.Fatalf("跨时区填写导致起止实际相等时应返回 ErrInvalidInterval, got %v", err)
356		}
357	
358		// 失败不留新版、不占用标识、不截短旧版、不改替代关系。
359		assertXtzOldUntruncated(t, b)
360	
361		// 修正为合法时间（结束 11:00+08 即 03:00Z），沿用同一标识 seat-v2 登记成功。
362		fixedEnd := xtzNewEnd
363		if err := b.RegisterVersion(RegisterRequest{
364			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
365			Start: xtzNewStart, End: &fixedEnd, Replaces: "seat-v1",
366		}); err != nil {
367			t.Fatalf("失败登记不应占用版本标识，修正为合法跨时区时间后应成功, got %v", err)
368		}
369		assertXtzReplacedState(t, b)
370	}
371	
372	// TestCrossTimezoneIndependentOfMachineLocalZone 把进程的本机默认时区逐个换成
373	// 不同偏移后重跑整条主线与两个失败边界：账本只按实际时刻判断，
374	// 结论不能随本机默认时区变化。所有业务时刻都在代码中写死并注入固定时钟，
375	// 因此同样不依赖运行当天的真实日期。
376	//
377	// 本包测试均不使用 t.Parallel，临时替换全局 time.Local 是安全的。
378	func TestCrossTimezoneIndependentOfMachineLocalZone(t *testing.T) {
379		localZones := []*time.Location{
380			time.UTC,
381			time.FixedZone("UTC+8", 8*3600),
382			time.FixedZone("UTC-5", -5*3600),
383			time.FixedZone("UTC+5:30", 5*3600+30*60),
384		}
385		for _, loc := range localZones {
386			loc := loc
387			t.Run(loc.String(), func(t *testing.T) {
388				saved := time.Local
389				time.Local = loc
390				t.Cleanup(func() { time.Local = saved })
391	
392				// 成功主线：登记 + 视图 + 交接点选择 + 到期不恢复。
393				b := newXtzReplacedBook(t)
394				assertXtzReplacedState(t, b)
395				if got, err := b.EffectiveVersionAt(
396					"seat", xtzHandoffUTC.Add(-time.Nanosecond)); err != nil || got.VersionID != "seat-v1" {
397					t.Fatalf("交接点前应选旧版: %v %+v", err, got)
398				}
399				if got, err := b.EffectiveVersionAt("seat", xtzHandoffUTC); err != nil || got.VersionID != "seat-v2" {
400					t.Fatalf("交接点应选新版: %v %+v", err, got)
401				}
402				if _, err := b.EffectiveVersionAt("seat", xtzNewEndUTC); !errors.Is(err, ErrNoEffectiveVersion) {
403					t.Fatalf("03:00Z 应无生效版本, got %v", err)
404				}
405	
406				// 失败边界一：起止实际相等 -> ErrInvalidInterval，失败后标识可复用。
407				b1 := newXtzOldOnlyBook(t)
408				badEnd := xtzBadEndEqualStart
409				if err := b1.RegisterVersion(RegisterRequest{
410					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
411					Start: xtzNewStart, End: &badEnd, Replaces: "seat-v1",
412				}); !errors.Is(err, ErrInvalidInterval) {
413					t.Fatalf("失败边界一应返回 ErrInvalidInterval, got %v", err)
414				}
415				assertXtzOldUntruncated(t, b1)
416	
417				// 失败边界二：替代开始恰等于旧版实际结束 -> ErrInvalidReplacement。
418				b2 := newXtzOldOnlyBook(t)
419				boundaryEnd := xtzBoundaryEnd
420				if err := b2.RegisterVersion(RegisterRequest{
421					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
422					Start: xtzBoundaryStart, End: &boundaryEnd, Replaces: "seat-v1",
423				}); !errors.Is(err, ErrInvalidReplacement) {
424					t.Fatalf("失败边界二应返回 ErrInvalidReplacement, got %v", err)
425				}
426				assertXtzOldUntruncated(t, b2)
427			})
428		}
429	}
430	
431	// TestCrossTimezoneInvalidReplacementStartEqualsOldEnd 失败边界二：
432	// 新版开始改为 13:00 (+08:00)（恰为旧版实际结束 05:00Z）、结束 14:00 (+08:00)，
433	// 请求自身区间合法，但替代开始必须严格落在旧版当前实际有效区间内，
434	// 端点相等不允许，必须返回 ErrInvalidReplacement 且整次登记回滚；
435	// 把开始修正为 02:00Z 后，同一新版标识仍能登记成功。
436	func TestCrossTimezoneInvalidReplacementStartEqualsOldEnd(t *testing.T) {
437		b := newXtzOldOnlyBook(t)
438	
439		// 失败前提：13:00+08 恰好等于旧版登记/实际结束 05:00Z；旧版尚未被替代。
440		if !xtzBoundaryStart.Equal(xtzOldEnd) {
441			t.Fatal("测试前提不成立：失败边界二的开始应恰好等于旧版实际结束")
442		}
443	
444		boundaryEnd := xtzBoundaryEnd
445		err := b.RegisterVersion(RegisterRequest{
446			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
447			Start: xtzBoundaryStart, End: &boundaryEnd, Replaces: "seat-v1",
448		})
449		if !errors.Is(err, ErrInvalidReplacement) {
450			t.Fatalf("替代开始恰好等于旧版实际结束时应返回 ErrInvalidReplacement, got %v", err)
451		}
452	
453		// 失败不留新版、不占用标识、不截短旧版、不改替代关系。
454		assertXtzOldUntruncated(t, b)
455	
456		// 修正为合法的交接时刻 02:00Z、结束 11:00+08（03:00Z），沿用同一标识成功。
457		fixedEnd := xtzNewEnd
458		if err := b.RegisterVersion(RegisterRequest{
459			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
460			Start: xtzNewStart, End: &fixedEnd, Replaces: "seat-v1",
461		}); err != nil {
462			t.Fatalf("失败登记不应占用版本标识，修正开始时刻后应成功, got %v", err)
463		}
464		assertXtzReplacedState(t, b)
465	
466		// 成功后再按实际时刻抽查选择结论：交接点前旧版、交接点新版、03:00Z 起无版本。
467		if got, err := b.EffectiveVersionAt("seat", xtzHandoffUTC.Add(-time.Nanosecond)); err != nil ||
468			got.VersionID != "seat-v1" {
469			t.Fatalf("交接点前应选旧版: %v %+v", err, got)
470		}
471		if got, err := b.EffectiveVersionAt("seat", xtzHandoffUTC); err != nil ||
472			got.VersionID != "seat-v2" {
473			t.Fatalf("交接点应选新版: %v %+v", err, got)
474		}
475		if _, err := b.EffectiveVersionAt("seat", xtzNewEndUTC); !errors.Is(err, ErrNoEffectiveVersion) {
476			t.Fatalf("新版到期后应无生效版本, got %v", err)
477		}
478	}
